'use strict';
const SWORD_SKILLS={};let swordSwipes=[],queuedAction=null,selectedSwordSkill=null,skillTier=1;
function emptySwordSkills(){return {}}
function legacySwordSkills(){return false}
function removedSwordPointRefund(){return 0}
function validateSwordSkills(){return {}}
function validateSkillSlots(){return {q:null,w:null,e:null,r:null}}
function skillTargets(key,reach,targets){return monsters.filter(m=>!m.dead&&(m.x-player.x)*player.face>=-(monsterRadius(m)+8)&&(m.x-player.x)*player.face<reach+monsterRadius(m)&&player.y>m.y-monsterHeight(m)-15&&player.y<m.y+46).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x)).slice(0,targets)}
function queueAction(action){if((player.cd.action||0)>0&&(player.cd.action||0)<=.22)queuedAction={action,life:.25};return false}
function tickQueuedAction(dt){if(!queuedAction)return;queuedAction.life-=dt;if(queuedAction.life<=0){queuedAction=null;return}if((player.cd.action||0)<=0){const next=queuedAction.action;queuedAction=null;if(next==='attack')act('attack');else if(WEAPON_SKILLS[next])castWeaponSkill(next);else queuedAction=null}}
function actionDelay(id){const base={attack:jobProfile().cooldown,slashBlast:.42,warriorLeap:.2,brandish:.45,flashSlash:.4,divineSwing:.45,pageOrder:.48,spearPulling:.45,beholderShock:.5}[id]||.4;return Math.max(.18,base*100/characterStatus().atkspd*(1-weaponLoadoutBonuses().recovery))}
function beginActionDelay(id){player.cd.action=actionDelay(id);player.swing=Math.max(player.swing||0,Math.min(.5,player.cd.action))}
function usePotion(kind){if(paused||screen!=='play'||run?.finished)return false;const maximum=kind==='hp'?maxHP():maxMP(),cd=kind==='hp'?'hpPotion':'mpPotion';if(player[kind]>=maximum||player.cd[cd]>0||!(player.consumables?.[cd]>0))return false;player.consumables[cd]--;const value=Math.min(maximum-player[kind],Math.ceil(maximum*.35));player[kind]+=value;player.cd[cd]=2;tutorialMark(cd);burst(player.x,player.y-20,kind==='hp'?'#f5a599':'#a3d3ff',12);tone(kind==='hp'?610:760,.12);save();updateUI();return true}
function updateSwordHUD(){updateWeaponHUD();return updatePotionHUD()}
function updatePotionHUD(){for(const [kind,id]of [['hp','hpPotionBtn'],['mp','mpPotionBtn']]){const cd=kind==='hp'?'hpPotion':'mpPotion',button=$(id),label=$(kind+'PotionCD');if(button){const stock=player.consumables?.[cd]??0;button.disabled=player.cd[cd]>0||stock===0;button.classList.toggle('empty-potion',stock===0);button.title='';let text=button.querySelector('.potion-kind');if(!text){text=document.createElement('b');text.className='potion-kind';button.append(text)}text.textContent=kind.toUpperCase();let count=button.querySelector('.potion-count');if(!count){count=document.createElement('strong');count.className='potion-count';button.append(count)}count.textContent=stock;button.setAttribute('aria-label','ยา '+kind.toUpperCase()+' '+(kind==='hp'?'Z':'X')+' · '+stock+' ขวด');button.onmouseenter=()=>showItemDetail(button,POTION_ITEMS[cd],stock);button.onmouseleave=()=>hideUpgradeTooltip(false)}if(label)label.textContent=player.cd[cd]>0?player.cd[cd].toFixed(1):''}}
function tickSwordSwipes(dt){player.dashTime=Math.max(0,(player.dashTime||0)-dt);if(player.ground)player.airLeapUsed=false;for(const swipe of swordSwipes)swipe.life-=dt;swordSwipes=swordSwipes.filter(s=>s.life>0)}
function drawSwordSwipes(){for(const s of swordSwipes){ctx.save();ctx.translate(s.x,s.y);ctx.scale(s.face,1);ctx.globalAlpha=Math.min(1,s.life*5);ctx.strokeStyle=s.key==='powerBash'?'#ffe1a0':'#d2f7c4';ctx.lineWidth=s.key==='powerBash'?7:4;ctx.beginPath();for(let i=0;i<9;i++){const angle=-1.05+i*.26,x=Math.cos(angle)*s.reach*.75,y=Math.sin(angle)*36;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.restore()}}
window.addEventListener('DOMContentLoaded',()=>{if($('hpPotionBtn'))$('hpPotionBtn').onclick=()=>usePotion('hp');if($('mpPotionBtn'))$('mpPotionBtn').onclick=()=>usePotion('mp')});
const POTION_ITEMS={hpPotion:{name:'ยาเพิ่ม HP',kind:'hp',description:'ฟื้นฟู HP 35% ของ HP สูงสุด · ใช้ด้วย Z · พักการใช้ยา 2 วินาที'},mpPotion:{name:'ยาเพิ่ม MP',kind:'mp',description:'ฟื้นฟู MP 35% ของ MP สูงสุด · ใช้ด้วย X · พักการใช้ยา 2 วินาที'}};
function validateConsumables(raw){if(raw===undefined)return {hpPotion:10,mpPotion:10};if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ข้อมูลยาไม่ถูกต้อง');const out={};for(const key of Object.keys(POTION_ITEMS)){const value=raw[key]??0;if(!Number.isInteger(value)||value<0||value>9999)throw Error('จำนวนยาไม่ถูกต้อง');out[key]=value}return out}
function showItemDetail(anchor,item,count,pinned=false){showUpgradeTooltip(anchor,item.name||item.item,[],item.description+(count!==undefined?'\nจำนวน '+count+' ขวด':''),pinned)}
function castAssignedSkill(slot){const id=player.weaponLoadout?.[['q','w','e','r'].indexOf(slot)]?.active[0];return id?castWeaponSkill(id):false}

